#define SZ 1000000
#define V 998244353
#define X 1000000007
#define LL long long
#define Dec(x) (!x--&&(x+=X))
using namespace std;

LL n, nn, p;
int ans, tn[7], c[7][7], s[7][7][SZ+1];

void init(int x, int l, const int& k) {
    s[k][l][++c[k][l]] = (++p) - x;
    if (l == k) return;
    for (int i = 0; i <= 9; ++i) init(x * 10 + i, l + 1, k);
