void brute(long long x, int l) {
    if (x > n) return;
    ++p;
    ans = (ans + (p - x) / V - (p < x) + X) % X;
    for (int i = 0; i <= 9; ++i) brute(x * 10 + i, l + 1);
}

void solve(int x, int l) {
    if (l != 6) {
        ++p;
        ans = (ans + (p - x) / V - (p < x) + X) % X;
        for (int i = 0; i <= 9; ++i) solve(x * 10 + i, l + 1);
        return;
    }
    if (x == nn) return brute(x, 0);
    int k; long long v;
    for (k = 0, v = x; k <= 6 && v <= n; ++k, v *= 10);
    --k;
    for (int i = 0; i <= k; ++i) {
        v = p - 1LL * x * tn[i];
        ans = (ans + 1LL * (v / V - (v < 0) + X) * tn[i]) % X;
        v = (v % V + V) % V;
        ans = (ans + tn[i] - (lower_bound(s[k][i] + 1, s[k][i] + tn[i] + 1, v) - s[k][i]) + 1) % X;
    }
    for (int i = 0; i <= k; ++i) p += tn[i];
}

int main() {
