    scanf("%lld", &n);
    tn[0] = i = 1;
    for (k = 1; k <= 6; ++k) tn[k] = tn[k - 1] * 10;
    for (k = 0; k <= 6; ++k) {
        p = 0;
        init(0, 0, k);
        for (i = 0; i <= k; ++i) sort(s[k][i] + 1, s[k][i] + tn[i] + 1);
    }
    p = 0;
    if (p == 0 && n < 1e6) {
        for (i = 1; i <= 9; ++i) brute(i, 1);
    } else {
        nn = n;
        while (nn >= 1e6) nn /= 10;
